import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    idx = 1

    dice = []
    K_list = []

    for _ in range(N):
        K = int(input_data[idx])
        K_list.append(K)
        idx += 1

        freq = {}
        for _ in range(K):
            val = int(input_data[idx])
            freq[val] = freq.get(val, 0) + 1
            idx += 1
        dice.append(freq)

    max_prob = 0.0

    for i in range(N):
        for j in range(i + 1, N):
            d1 = dice[i]
            d2 = dice[j]

            if len(d1) > len(d2):
                d1, d2 = d2, d1

            match_sum = 0
            for val, count in d1.items():
                match_sum += count * d2.get(val, 0)

            prob = match_sum / (K_list[i] * K_list[j])
            if prob > max_prob:
                max_prob = prob

    print(max_prob)

if __name__ == "__main__":
    solve()
